    def __init__(self):
        self._generation = 0  # current generation
        self._rows = []
        self._decisions = {}
        self.busy = False
        self._latest_completed_generation = None  # generation that completed and pending fetch
        self._fetched_generations = set()  # generations already fetched via finish

    def start(self):
        # Increment generation; preserve rows and decisions
        self._generation += 1
        self.busy = True
        # rows and decisions are preserved
        return self._generation

    def poll_status(self, generation, status):
        # Only consider status reports for the current generation
        if generation != self._generation:
            return False
        if status in ("queued", "running"):
            # keep busy
            return False
        if status == "failed":
            self.busy = False
            return False
        if status == "completed":
            # if this is the latest running generation and not yet fetched
            if self._latest_completed_generation is None:
                self._latest_completed_generation = generation
                # return True once to fetch
                return True
            else:
                return False
        return False

    def finish(self, generation, rows):
        # Only accept if this is the latest completed generation and not yet fetched
        if generation != self._generation or generation != self._latest_completed_generation:
            return False
        if generation in self._fetched_generations:
            return False
        # copy rows and end busy
        self._rows = rows
        self.busy = False
        self._fetched_generations.add(generation)
        self._latest_completed_generation = None
        return True

    def set_decision(self, job_id, value):
        self._decisions[job_id] = value

    # Expose rows and decisions for testing
    @property
    def rows(self):
        return self._rows

    @property
    def decisions(self):
        return self._decisions
